-- Create "route_http" table
CREATE TABLE "route_http" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "org_id" character varying NOT NULL, "path_prefix" character varying NOT NULL DEFAULT '', "header_matches" jsonb NULL, "tls_mode" character varying NOT NULL DEFAULT 'acme', "port80" character varying NOT NULL DEFAULT 'redirect', "host_header" character varying NOT NULL DEFAULT 'preserve', "request_headers_set" jsonb NULL, "response_headers_set" jsonb NULL, "websocket" boolean NOT NULL DEFAULT true, "max_body_bytes" bigint NOT NULL DEFAULT 0, "dns_proxied" boolean NOT NULL DEFAULT false, "route_id" character varying NOT NULL, "certificate_id" character varying NULL, PRIMARY KEY ("id"), CONSTRAINT "route_http_certificates_certificate" FOREIGN KEY ("org_id", "certificate_id") REFERENCES "certificates" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "route_http_routes_route" FOREIGN KEY ("org_id", "route_id") REFERENCES "routes" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "route_http_orgs" FOREIGN KEY ("org_id") REFERENCES "orgs" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "routehttp_certificate_id" to table: "route_http"
CREATE INDEX "routehttp_certificate_id" ON "route_http" ("certificate_id");
-- Create index "routehttp_org_id_id" to table: "route_http"
CREATE UNIQUE INDEX "routehttp_org_id_id" ON "route_http" ("org_id", "id");
-- Create index "routehttp_route_id" to table: "route_http"
CREATE UNIQUE INDEX "routehttp_route_id" ON "route_http" ("route_id");
